import { exportedSnapshot, loadTimedBoard } from './game-fixture.ts';

test('editing a deal name preserves live progress, mismatch timing and board drafts', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('.card').nth(2).click();
  await page.locator('.card').nth(6).click();
  await page.locator('.card').nth(0).click();
  await page.locator('.card').nth(1).click();
  await page.clock.runFor(125);
  const before = await exportedSnapshot(page);
  await page.locator('.card').nth(9).focus();
  await page.locator('summary').click();
  const field = page.getByRole('textbox', { name: 'Deal name', exact: true });
  await expect(field).toHaveValue('');
  await expect(field).toHaveAttribute('type', 'text');
  await expect(field).toHaveAttribute('maxlength', '40');
  const board = page.getByLabel('Board code', { exact: true });
  await board.fill('unfinished board draft');
  await field.fill(' Café 😀 ');
  await expect(field).toBeFocused();
  await expect(page.locator('.card').nth(9)).toHaveAttribute('tabindex', '0');
  const exportButton = page.getByRole('button', { name: 'Export snapshot', exact: true });
  await exportButton.click();
  await expect(exportButton).toBeFocused();
  const snapshot = page.getByLabel('Snapshot JSON', { exact: true });
  expect(JSON.parse(await snapshot.inputValue())).toEqual({
    ...before,
    version: 2,
    name: ' Café 😀 ',
  });
  await expect(board).toHaveValue('unfinished board draft');
  await expect(page.getByRole('status')).toHaveText('No match. Cards close after a short pause.');
  await page.clock.runFor(674);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await expect(page.locator('.card.revealed')).toHaveCount(0);
  await expect(page.locator('.card.matched')).toHaveCount(2);
  await field.fill('');
  await exportButton.click();
  expect(JSON.parse(await snapshot.inputValue())).toEqual({
    ...before,
    selection: { kind: 'closed' },
    elapsedMs: 800,
  });
});

test('the name control keeps Unicode and spaces within forty UTF-16 units and rejects multiline paste', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('summary').click();
  const field = page.getByLabel('Deal name', { exact: true });
  const name = '😀'.repeat(20);
  await field.fill(name);
  await field.press('End');
  await field.pressSequentially('x');
  await expect(field).toHaveValue(name);
  const rejected = await field.evaluate((input) => {
    const data = new DataTransfer();
    data.setData('text/plain', 'bad\r\nname');
    return !input.dispatchEvent(
      new ClipboardEvent('paste', { clipboardData: data, bubbles: true, cancelable: true }),
    );
  });
  expect(rejected).toBe(true);
  await expect(field).toHaveValue(name);
  await field.fill(' Café ');
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toMatchObject({ version: 2, name: ' Café ' });
});
import { expect, test } from './browser-test.ts';
import { exportedSnapshot, loadTimedBoard } from './game-fixture.ts';

test('pasted reordered named progress stays paused during rename and resumes its saved interval', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('summary').click();
  const field = page.getByLabel('Deal name', { exact: true });
  const draft = page.getByLabel('Snapshot JSON', { exact: true });
  const snapshot = {
    name: ' Café ',
    started: true,
    moves: 2,
    elapsedMs: 1500,
    selection: { remainingMs: 300, second: 2, first: 1, kind: 'mismatch' },
    matched: [0, 11],
    boardCode: 'np1-4-1',
    version: 2,
  };
  await draft.fill(JSON.stringify(snapshot));
  const load = page.getByRole('button', { name: 'Load snapshot', exact: true });
  await load.click();
  await expect(load).toBeFocused();
  await expect(field).toHaveValue(snapshot.name);
  await expect(page.locator('.load-notice')).toHaveText(
    'Loaded snapshot. Select Resume to continue.',
  );
  await field.fill('Renamed while paused');
  await page.locator('.card').nth(2).click();
  await page.keyboard.press('ArrowRight');
  await page.keyboard.press('Enter');
  await expect(page.locator('.card').nth(3)).toBeFocused();
  await page.clock.runFor(2000);
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toEqual({
    ...snapshot,
    name: 'Renamed while paused',
  });
  await page.getByRole('button', { name: 'Resume', exact: true }).click();
  await expect(page.locator('.card').nth(3)).toBeFocused();
  await page.clock.runFor(299);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await expect(page.locator('.card.revealed')).toHaveCount(0);
  expect(await exportedSnapshot(page)).toMatchObject({
    name: 'Renamed while paused',
    elapsedMs: 1800,
    selection: { kind: 'closed' },
  });
  await page.locator('summary').click();
  const { name: _name, ...unnamed } = snapshot;
  await draft.fill(JSON.stringify({ ...unnamed, version: 1 }));
  await load.click();
  await expect(field).toHaveValue('');
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toBeVisible();
});

test('invalid named imports keep the current name, game and draft available for correction', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('.card').nth(2).click();
  await page.clock.runFor(125);
  await page.locator('summary').click();
  const field = page.getByLabel('Deal name', { exact: true });
  await field.fill('Keep me');
  await page.locator('summary').click();
  const before = await exportedSnapshot(page);
  await page.locator('summary').click();
  const invalid = JSON.stringify({ ...before, name: 'bad\nname' });
  const draft = page.getByLabel('Snapshot JSON', { exact: true });
  await draft.fill(invalid);
  const load = page.getByRole('button', { name: 'Load snapshot', exact: true });
  await load.click();
  await expect(load).toBeFocused();
  await expect(draft).toHaveValue(invalid);
  await expect(field).toHaveValue('Keep me');
  await expect(page.locator('.load-notice')).toHaveText('Invalid snapshot.');
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toHaveCount(0);
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toEqual(before);
  await page.clock.runFor(100);
  expect(await exportedSnapshot(page)).toMatchObject({ ...before, elapsedMs: 225 });
});
import { expect, test } from './browser-test.ts';
import { exportedSnapshot, finishBoard, loadTimedBoard } from './game-fixture.ts';

test('new deals, restart, board loads, size changes and reload clear names without saving them', async ({
  page,
  gameURL,
}) => {
  await loadTimedBoard(page, gameURL);
  await page.locator('summary').click();
  const field = page.getByLabel('Deal name', { exact: true });
  for (const action of ['New Game', 'Restart', 'Load board', 'Grid size']) {
    await field.fill('A name that stays out of preferences');
    if (action === 'Grid size')
      await page.getByRole('combobox', { name: action, exact: true }).selectOption('6');
    else {
      if (action === 'Load board')
        await page.getByLabel('Board code', { exact: true }).fill('np1-4-2');
      await page.getByRole('button', { name: action, exact: true }).click();
    }
    await expect(field).toHaveValue('');
    await page.getByRole('button', { name: 'Export snapshot', exact: true }).click();
    expect(
      JSON.parse(await page.getByLabel('Snapshot JSON', { exact: true }).inputValue()),
    ).toMatchObject({ version: 1, started: false, moves: 0, elapsedMs: 0 });
  }
  await field.fill('A name that stays out of preferences');
  expect(await page.evaluate(() => JSON.stringify(localStorage))).not.toContain(
    'A name that stays out of preferences',
  );
  await page.reload();
  await expect(page.getByRole('combobox', { name: 'Grid size', exact: true })).toHaveValue('6');
  await expect(page.locator('.card')).toHaveCount(36);
  await expect(page.locator('details')).not.toHaveAttribute('open');
  await page.locator('summary').click();
  await expect(field).toHaveValue('');
});

test('completed named imports stay static and renamable while resumed wins still record bests', async ({
  page,
  gameURL,
}) => {
  await loadTimedBoard(page, gameURL);
  await page.locator('.card').nth(0).click();
  await page.locator('.card').nth(1).click();
  await page.clock.runFor(800);
  await finishBoard(page);
  await expect(page.locator('.stats dd').nth(3)).toHaveText('9');
  await page.locator('summary').click();
  const field = page.getByLabel('Deal name', { exact: true });
  await field.fill('Already completed');
  const draft = page.getByLabel('Snapshot JSON', { exact: true });
  const completed = {
    boardCode: 'np1-4-1',
    name: 'Saved winner',
    matched: Array.from({ length: 16 }, (_, index) => index),
    selection: { kind: 'closed' },
    moves: 8,
    elapsedMs: 1000,
    started: true,
    version: 2,
  };
  await draft.fill(JSON.stringify(completed));
  const load = page.getByRole('button', { name: 'Load snapshot', exact: true });
  await load.click();
  await expect(field).toHaveValue('Saved winner');
  await expect(page.locator('.victory')).not.toHaveClass(/celebrate/);
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toHaveCount(0);
  await expect(page.locator('.load-notice')).toHaveText('Loaded completed snapshot.');
  await expect(page.locator('.stats dd').nth(3)).toHaveText('9');
  await field.fill('Renamed winner');
  await page.clock.runFor(2000);
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toEqual({ ...completed, name: 'Renamed winner' });
  await expect(page.locator('.victory')).not.toHaveClass(/celebrate/);
  await expect(page.locator('.stats dd').nth(3)).toHaveText('9');
  await page.locator('summary').click();
  await draft.fill(
    JSON.stringify({
      ...completed,
      matched: completed.matched.filter((index) => index !== 2 && index !== 6),
      selection: { kind: 'one', index: 2 },
      moves: 7,
      name: 'Finish this one',
    }),
  );
  await load.click();
  await page.getByRole('button', { name: 'Resume', exact: true }).click();
  await page.locator('.card').nth(6).click();
  await expect(page.locator('.card.matched')).toHaveCount(16);
  await expect(page.locator('.stats dd').nth(3)).toHaveText('8');
  await expect(field).toHaveValue('Finish this one');
});

